import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long c = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cap = (int) n + 2;
        long[] ms = new long[cap];
        long[] bs = new long[cap];
        int head = 0, size = 1;
        long x = 0, dp = 0;
        for (int i = 0; i < n; i++) {
            x += a[i];
            while (head + 1 < size && ms[head + 1] * x + bs[head + 1] <= ms[head] * x + bs[head]) head++;
            dp = ms[head] * x + bs[head] + x * x + c;
            long m3 = -2 * x, b3 = dp + x * x;
            while (size - head >= 2 && (b3 - bs[size - 2]) * (ms[size - 2] - ms[size - 1]) <= (bs[size - 1] - bs[size - 2]) * (ms[size - 2] - m3)) size--;
            ms[size] = m3;
            bs[size] = b3;
            size++;
        }
        System.out.println(dp);
    }
}
